using System;
using Unity.Netcode;
using UnityEditor;
using UnityEngine;

namespace Pretzel.Multiplayer.Editor
{
    /// <summary>Saves GameObjects as network prefab assets and verifies NGO assigned a GlobalObjectIdHash (it is generated by NetworkObject.OnValidate on the asset).</summary>
    public static class NetworkPrefabAssetUtility
    {
        /// <summary>
        /// Saves <paramref name="root"/> as a prefab asset at <paramref name="assetPath"/>, destroys the scene instance and returns the asset.
        /// Throws when the prefab has a NetworkObject whose GlobalObjectIdHash is still 0 after import, because such a prefab cannot be spawned.
        /// </summary>
        public static GameObject SavePrefab(GameObject root, string assetPath)
        {
            string folder = System.IO.Path.GetDirectoryName(assetPath).Replace('\\', '/');
            AssetFolderUtility.EnsureFolder(folder);
            GameObject asset = PrefabUtility.SaveAsPrefabAsset(root, assetPath);
            UnityEngine.Object.DestroyImmediate(root);
            AssetDatabase.ImportAsset(assetPath, ImportAssetOptions.ForceUpdate);
            asset = AssetDatabase.LoadAssetAtPath<GameObject>(assetPath);
            NetworkObject networkObject = asset.GetComponent<NetworkObject>();
            if (networkObject != null && networkObject.PrefabIdHash == 0)
            {
                // OnValidate generates the hash; touching the asset makes the editor run it.
                EditorUtility.SetDirty(asset);
                AssetDatabase.SaveAssetIfDirty(asset);
                AssetDatabase.ImportAsset(assetPath, ImportAssetOptions.ForceUpdate);
                asset = AssetDatabase.LoadAssetAtPath<GameObject>(assetPath);
                networkObject = asset.GetComponent<NetworkObject>();
                if (networkObject.PrefabIdHash == 0)
                {
                    throw new InvalidOperationException($"NGO did not assign a GlobalObjectIdHash to '{assetPath}'. Open the prefab once in the Editor and save it.");
                }
            }

            return asset;
        }
    }
}
